package local.tvmorph.playercheck;
import android.app.*;import android.content.*;import android.os.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
/** Authenticated receiver route: INPUT aliases must open native sources, never fall through to web keys. */
public class RemoteInputInstrumentation extends Instrumentation {
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{Activity owner=startActivitySync(new Intent().setClassName("local.tvmorph.tv","local.tvmorph.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(750);Class<?> type=owner.getClass();Field coverField=type.getDeclaredField("startupCover");coverField.setAccessible(true);android.widget.ImageView logo=(android.widget.ImageView)((android.widget.LinearLayout)coverField.get(owner)).getChildAt(0);android.graphics.drawable.BitmapDrawable artwork=(android.graphics.drawable.BitmapDrawable)logo.getDrawable();if(artwork.getBitmap().getWidth()<2000||!artwork.getPaint().isFilterBitmap())throw new AssertionError("Loading logo must retain full-resolution filtered bitmap");Field webField=type.getDeclaredField("web");webField.setAccessible(true);android.webkit.WebView web=(android.webkit.WebView)webField.get(owner);boolean metrics=false;for(int attempt=0;attempt<80&&!metrics;attempt++){java.util.concurrent.CountDownLatch ready=new java.util.concurrent.CountDownLatch(1);String[] checked={null};runOnMainSync(()->web.evaluateJavascript("(function(){var h=document.getElementById('nav-home'),c=document.getElementById('nav-connect-phone'),l=document.getElementById('nav-language');if(!h||!c||!l)return false;var a=getComputedStyle(h),b=getComputedStyle(c),d=getComputedStyle(l);return a.fontSize===b.fontSize&&a.fontSize===d.fontSize&&a.lineHeight===b.lineHeight&&a.lineHeight===d.lineHeight;})()",r->{checked[0]=r;ready.countDown();}));ready.await(5,java.util.concurrent.TimeUnit.SECONDS);metrics="true".equals(checked[0]);if(!metrics)Thread.sleep(100);}if(!metrics)throw new AssertionError("Native Connect phone/Language must match Home typography");java.util.concurrent.CountDownLatch visual=new java.util.concurrent.CountDownLatch(1);String[] visualResult={null};runOnMainSync(()->web.evaluateJavascript("(function(){var tools=document.querySelector('#view-home .home-tools'),store=document.getElementById('home-store'),button=Array.from(document.querySelectorAll('#favourites.app-dock>button')).filter(function(n){return n.offsetWidth&&!n.hidden&&!n.disabled;})[0];if(!tools||!store||!button)return {error:'Missing launcher controls'};button.focus();var r=tools.getBoundingClientRect();return {focused:document.activeElement===button,button:button.id,classes:document.body.className,sideCenter:r.top+r.height/2,screenCenter:innerHeight/2,arrow:store.textContent.indexOf('↗')>=0,opacity:getComputedStyle(button,'::before').opacity};})()",r->{visualResult[0]=r;visual.countDown();}));visual.await(5,java.util.concurrent.TimeUnit.SECONDS);JSONObject view=new JSONObject(visualResult[0]);if(view.has("error"))throw new AssertionError(view.toString());if(view.optBoolean("arrow")||Math.abs(view.getDouble("sideCenter")-view.getDouble("screenCenter"))>4||view.getDouble("opacity")>.23)throw new AssertionError("Launcher visual controls: "+view);Class<?> updater=getTargetContext().getClassLoader().loadClass("local.tvmorph.tv.OfficialUpdate");Method compare=updater.getDeclaredMethod("compare",String.class,String.class);compare.setAccessible(true);if(((Integer)compare.invoke(null,"0.8.288-remote-fix","0.8.289"))>=0||((Integer)compare.invoke(null,"0.8.289-preview","0.8.289"))!=0)throw new AssertionError("Update versions with build suffixes must compare correctly");Field token=type.getDeclaredField("token");token.setAccessible(true);Map<String,String> headers=new HashMap<>();headers.put("x-tv-morph-token",String.valueOf(token.get(owner)));Method handle=type.getDeclaredMethod("handle",String.class,String.class,Map.class,byte[].class);handle.setAccessible(true);Object response=handle.invoke(owner,"POST","/remote/key",headers,new JSONObject().put("key","INPUT").toString().getBytes("UTF-8"));Field code=response.getClass().getDeclaredField("code"),data=response.getClass().getDeclaredField("data");code.setAccessible(true);data.setAccessible(true);Class<?> sources=getTargetContext().getClassLoader().loadClass("local.tvmorph.tv.InputSources");Method picker=sources.getDeclaredMethod("preferred",Activity.class);picker.setAccessible(true);boolean hasNativePicker=picker.invoke(null,owner)!=null;if(code.getInt(response)!=200||new JSONObject(new String((byte[])data.get(response),"UTF-8")).optBoolean("sent")!=hasNativePicker)throw new AssertionError("INPUT must report whether a real firmware source panel can be opened");Thread.sleep(350);result.putString("result","PASS equal native header typography, full-resolution 2172px filtered launcher loading logo and authenticated Android INPUT receiver route accurately reports native firmware selector availability. Physical HDMI switching remains device-specific.");finish(Activity.RESULT_OK,result);}catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
}
